function reverseScheduleWorkOrders(workOrders, overtime) {
    let tasks = [];
    let schedule = [null, null, null, null, null, null];
    let accumulatedOvertime = 0;

    let shiftStart = 9;  // 9 AM
    let shiftEnd = 17;  // 5 PM

    // Sort the work orders by promise date in descending order
    workOrders.sort((a, b) => b.promiseDate - a.promiseDate);

    // Initialize the current date time to the promise date of the first work order (which is the latest)
    let currentDateTime = new Date(workOrders[0].promiseDate);
    currentDateTime.setHours(shiftEnd);
    currentDateTime.setMinutes(0);
    currentDateTime.setSeconds(0);

    for (let workOrder of workOrders) {
        for (let i = workOrder.processes.length - 1; i >= 0; i--) {
            let process = workOrder.processes[i];
            let taskDurationHours = workOrder.quantity / process.rate;
            let taskDurationMillisecs = taskDurationHours * 60 * 60 * 1000;

            // Determine the latest available time for this process
            let processAvailableTime = schedule[process.id] ? new Date(schedule[process.id]) : new Date(currentDateTime);
            // The task can end either before the next task starts or when the process is available, whichever is earlier
            let taskEnd = new Date(Math.min(currentDateTime, processAvailableTime));
            let taskStart = new Date(taskEnd.getTime() - taskDurationMillisecs);

            // Check if the task start time extends before the current shift, if so, extend to the previous shift
            if (taskStart.getHours() < shiftStart || (taskStart.getHours() === shiftStart && taskStart.getMinutes() < 0)) {
                // If overtime is allowed and the task start time is within the overtime window, accumulate the overtime
                if (overtime > 0 && taskStart.getHours() >= shiftStart - overtime) {
                    let overtimeUsed = shiftStart - taskStart.getHours() - (taskStart.getMinutes() < 0 ? 1 : 0);
                    accumulatedOvertime += overtimeUsed;
                } else {
                    // If no overtime is allowed or the task start time is beyond the overtime window, move the task to the next shift
                    taskEnd.setDate(taskEnd.getDate() - 1);
                    taskEnd.setHours(shiftEnd);
                    taskEnd.setMinutes(0);
                    taskEnd.setSeconds(0);
                    taskStart = new Date(taskEnd.getTime() - taskDurationMillisecs);
                }
            }

            tasks.unshift({
                "workOrderId": workOrder.id,
                "processLabel": process.label,
                "start": taskStart,
                "end": taskEnd,
                "color":workOrder.color
            });

            // Update the current date time to the start of this task
            currentDateTime = new Date(taskStart);
            // Update the schedule array with the start time of this task for this process
            schedule[process.id] = taskStart;
        }
    }

    return { "tasks": tasks, "accumulatedOvertime": accumulatedOvertime };
};

