    edges {
      node {
        id number
        promiseAt
        scheduledFinishAt
        scheduledStartAt
        workOrderDistributions {
          edges {
            node {
              scheduledFinishAt
              scheduledStartAt
              workOrderProcess {
                order
                quantity
                code
                productionOperators
                setupOperators
              }
              workcenter {
                code
              }
            }
          }
        }
      }
    }
  }
}

