function scheduleWorkOrders(workOrders, overtime) {
    let tasks = [];
    let schedule = [null, null, null, null, null, null, null, null];
    let accumulatedOvertime = 0;

    let currentDateTime = new Date(workOrders[0].promiseDate);
    currentDateTime.setHours(6, 0, 0, 0);

    let normalShiftDurationMillisecs = 12 * 60 * 60 * 1000;
    let totalShiftDurationMillisecs = (12 + overtime) * 60 * 60 * 1000;

    let earliestStartDate = null;
    let latestEndDate = null;

    for (let workOrder of workOrders) {
        let lastTaskEndTimeInThisWorkOrder = new Date(currentDateTime);

        for (let process of workOrder.processes) {
            let taskDurationMillisecs = (workOrder.quantity / process.rate) * 60 * 60 * 1000;

            let processAvailableTime = schedule[process.id] ? new Date(schedule[process.id]) : new Date(currentDateTime);

            let taskStart = new Date(Math.max(lastTaskEndTimeInThisWorkOrder.getTime(), processAvailableTime.getTime()));

            let shiftStart = new Date(taskStart);
            shiftStart.setHours(6, 0, 0, 0);

            let shiftEnd = new Date(shiftStart);
            shiftEnd.setTime(shiftStart.getTime() + totalShiftDurationMillisecs);

            if (taskStart > shiftEnd) {
                shiftStart.setDate(shiftStart.getDate() + 1);
                shiftEnd.setDate(shiftEnd.getDate() + 1);
                taskStart = new Date(shiftStart);
            }

            let taskEnd = new Date(taskStart.getTime() + taskDurationMillisecs);

            if (taskEnd > shiftEnd) {
                let overtimeUsedMillisecs = taskEnd - shiftEnd;

                if (overtimeUsedMillisecs <= overtime * 60 * 60 * 1000) {
                    accumulatedOvertime += overtimeUsedMillisecs / (60 * 60 * 1000);
                } else {
                    shiftStart.setDate(shiftStart.getDate() + 1);
                    shiftEnd.setDate(shiftEnd.getDate() + 1);
                    taskStart = new Date(shiftStart);
                    taskEnd = new Date(taskStart.getTime() + taskDurationMillisecs);
                }
            }

            tasks.push({
                "workOrderId": workOrder.id,
                "processLabel": process.label,
                "start": taskStart,
                "end": taskEnd,
                "color": workOrder.color
            });

            if (!earliestStartDate || taskStart < earliestStartDate) {
                earliestStartDate = taskStart;
            }

            if (!latestEndDate || taskEnd > latestEndDate) {
                latestEndDate = taskEnd;
            }

            lastTaskEndTimeInThisWorkOrder = new Date(taskEnd);
            schedule[process.id] = taskEnd;
        }
    }

    return { 
        "tasks": tasks, 
        "accumulatedOvertime": accumulatedOvertime,
        "earliestStartDate": earliestStartDate,
        "latestEndDate": latestEndDate
    };
};


